<script setup>import { Play, Check, LockKeyhole, Sparkles } from 'lucide-vue-next'; import { programs } from '../../data/content'</script>
<template><div><div class="app-page-title"><div><span class="eyebrow soft">Tunde’s learning</span><h1>Learning journey</h1><p>Courses, daily activities and recommended next steps.</p></div><RouterLink class="button" to="/play/tunde/home">Enter child mode <Play fill="currentColor"/></RouterLink></div><section class="learning-plan panel"><div><span class="icon-circle yellow"><Sparkles/></span><h2>Today’s 20-minute plan</h2><p>A balanced mix based on current skills.</p></div><div class="session-items"><article><span class="done"><Check/></span><div><b>Meet Letter D</b><small>Completed · 4 min</small></div></article><article><span class="current">D</span><div><b>Trace Letter D</b><small>Up next · 5 min</small></div><RouterLink to="/play/tunde/activity/trace-letter-d"><Play/></RouterLink></article><article><span>5</span><div><b>Count to five</b><small>Numbers · 4 min</small></div></article><article><span>●</span><div><b>Colour match</b><small>Colours · 5 min</small></div></article></div></section><h2 class="subheading">Enrolled programs</h2><div class="enrolled-grid"><article v-for="program in programs.slice(0,4)" :key="program.slug" class="enrolled-card"><img :src="program.image" :alt="program.title"><div><span>{{program.subject}}</span><h3>{{program.title}}</h3><p>{{program.progress ? `${Math.ceil(program.lessons*program.progress/100)} of ${program.lessons} lessons` : 'Ready to begin'}}</p><div class="progress"><i :style="`width:${program.progress}%`"></i></div><RouterLink :to="`/courses/${program.slug}`">{{program.progress?'Continue':'Start course'}} →</RouterLink></div></article></div></div></template>
